def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            return -q
        return q

    def parse_expr() -> int | str:
        left = parse_term()
        while True:
            skip()
            if i >= n or s[i] not in "+-":
                return left
            op = s[i]
            i += 1
            right = parse_term()
            if left == "error" or right == "error":
                left = "error"
            elif op == "+":
                left = left + right
            else:
                left = left - right

    def parse_term() -> int | str:
        left = parse_unary()
        while True:
            skip()
            if i >= n or s[i] not in "*/%":
                return left
            op = s[i]
            i += 1
            right = parse_unary()
            if left == "error" or right == "error":
                left = "error"
            elif op == "*":
                left = left * right
            elif right == 0:
                left = "error"
            elif op == "/":
                left = trunc_div(left, right)
            else:
                left = left - right * trunc_div(left, right)

    def parse_unary() -> int | str:
        skip()
        if i < n and s[i] == "-":
            i += 1
            value = parse_unary()
            if value == "error":
                return "error"
            return -value
        return parse_power()

    def parse_power() -> int | str:
        base = parse_primary()
        skip()
        if i >= n or s[i] != "^":
            return base
        i += 1
        exp = parse_unary()
        if base == "error" or exp == "error" or exp < 0:
            return "error"
        return base ** exp

    def parse_primary() -> int | str:
        skip()
        if s[i] == "(":
            i += 1
            value = parse_expr()
            skip()
            i += 1  # ')'
            return value
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    return parse_expr()
